def grep(pattern, flags, files):
    flag_set = set(flags.split())
    case_insensitive = "-i" in flag_set
    inverted = "-v" in flag_set
    whole_line = "-x" in flag_set
    line_numbers = "-n" in flag_set
    file_names = "-l" in flag_set

    pattern = pattern.lower() if case_insensitive else pattern

    output = []
    for fname in files:
        with open(fname) as f:
            lines = f.readlines()
        if file_names:
            matched = False
            for line in lines:
                content = line.rstrip("\n")
                matches = pattern == content if whole_line else pattern in content
                if matches != inverted:
                    matched = True
            if matched:
                output.append(fname + "\n")
        else:
            prefix = fname + ":" if len(files) > 1 else ""
            for lineno, line in enumerate(lines, 1):
                content = line.rstrip("\n")
                matches = pattern == content if whole_line else pattern in content
                if matches != inverted:
                    prefix_ = prefix
                    if line_numbers:
                        prefix_ += str(lineno) + ":"
                    output.append(prefix_ + line)
    return "".join(output)
